--
-- Table structure for table `auth_session`
--

DROP TABLE IF EXISTS `auth_session`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `auth_session` (
  `id` varchar(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会话ID，UUID，同时作为 access token 的 jti 声明',
  `user_id` int NOT NULL COMMENT '所属用户ID，用户删除时级联删除会话',
  `refresh_token_hash` char(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'refresh token 的 SHA-256 哈希值（不存原始令牌），刷新时轮换',
  `expires_time` datetime(3) NOT NULL COMMENT '会话过期时间，超过后 refresh token 不可用',
  `revoked_time` datetime(3) DEFAULT NULL COMMENT '撤销时间，非空表示会话已注销（注销/改密/超额淘汰），保留一段时间用于审计',
  `last_used_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '最后使用时间，登录和刷新令牌时更新，用于淘汰最久未使用的会话',
  `ip_address` varchar(45) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '登录/刷新时的客户端 IP（已归一化，最长 45 字符兼容 IPv6）',
  `user_agent` varchar(512) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '登录/刷新时的客户端 User-Agent，用于展示设备信息',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `update_time` datetime(3) NOT NULL COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `auth_session_refresh_token_hash_key` (`refresh_token_hash`),
  KEY `auth_session_user_id_revoked_time_expires_time_idx` (`user_id`,`revoked_time`,`expires_time`),
  CONSTRAINT `auth_session_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='认证会话表，一行代表一次登录产生的会话（refresh token 的生命周期）';
/*!40101 SET character_set_client = @saved_cs_client */;

