DROP TABLE IF EXISTS `user`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `user` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '用户ID，自增主键',
  `username` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户名，全局唯一，用于登录',
  `password` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '密码的 bcrypt 哈希值（不存明文）',
  `email` varchar(191) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱，可选，全局唯一',
  `create_time` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT '创建时间',
  `update_time` datetime(3) NOT NULL COMMENT '更新时间',
  `role` enum('ADMIN','USER') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'USER' COMMENT '用户角色：ADMIN 管理员 / USER 普通用户',
